using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Windows;
using System.Windows.Automation;
using System.Windows.Controls;
using System.Windows.Data;
using Microsoft.Win32;

internal sealed class DpsHistorySummary {
    internal DpsHistoryRecord Record;internal string PlayerFilter;
    public string Started {get{return DpsHistory.LocalTime(Record.Started).ToString("dd MMM · HH:mm:ss",CultureInfo.CurrentCulture);}}
    public double Duration {get{return Record.Duration;}}
    public int Players {get{int value=0;foreach(var p in Record.Players)if(PlayerFilter==null||p.Name==PlayerFilter)value++;return value;}}
    public long Damage {get{long value=0;foreach(var p in Record.Players)if(PlayerFilter==null||p.Name==PlayerFilter)value+=p.Damage;return value;}}
    public long Healing {get{long value=0;foreach(var p in Record.Players)if(PlayerFilter==null||p.Name==PlayerFilter)value+=p.Healing;return value;}}
    public long Received {get{long value=0;foreach(var p in Record.Players)if(PlayerFilter==null||p.Name==PlayerFilter)value+=p.HealingReceived;return value;}}
}
internal sealed class DpsHistoryRoleConverter:IValueConverter {
    readonly string language;internal DpsHistoryRoleConverter(string value){language=value;}
    public object Convert(object value,Type type,object parameter,CultureInfo culture){byte role=(byte)value;return UiLanguage.Text(role==3?"Tank":role==2?"Healer / support":role==1?"Damage":"Unknown",language);}
    public object ConvertBack(object value,Type type,object parameter,CultureInfo culture){throw new NotSupportedException();}
}
internal sealed class DpsHistoryPane:Grid {
    readonly EnergyOverlay owner;readonly Window window;readonly CheckBox autoDelete=new CheckBox();readonly SettingsNumber minimum=new SettingsNumber("Minimum fight duration",0,3600,0,5),age=new SettingsNumber("Delete records older than",1,3650,0,1),maximum=new SettingsNumber("Maximum records",1,1000,0,1);
    readonly ComboBox unit=new ComboBox{Width=108,Height=34},playerPicker=new ComboBox{Width=190,Height=34};readonly DataGrid encounters=DpsEncounterDetails.NewTable();readonly ScrollViewer scroller;readonly DpsEncounterDetails analysis;readonly TextBlock count=SettingsVisual.Text("",12,"#929CAD"),detail=SettingsVisual.Text("",11,"#8994A6"),message=SettingsVisual.Text("",11,"#C5A783");readonly Button export,clear;readonly Expander storage;
    long revision=-1;int savedCount;bool loading;string language,playerFilter,style;DpsHistoryRecord selected;
    internal DpsHistoryPane(EnergyOverlay parent,Window settings){owner=parent;window=settings;var content=new StackPanel{Margin=new Thickness(0,0,10,0)};scroller=new ScrollViewer{Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,Background=System.Windows.Media.Brushes.Transparent};scroller.SetResourceReference(FrameworkElement.StyleProperty,"SlimScroll");Children.Add(scroller);
        var retention=new StackPanel();retention.Children.Add(Row("Automatically delete old records",autoDelete));var ageTools=new WrapPanel();ageTools.Children.Add(age);unit.Margin=new Thickness(8,0,0,0);unit.Items.Add(new ComboBoxItem{Content="Hours",Tag="hours"});unit.Items.Add(new ComboBoxItem{Content="Days",Tag="days"});ageTools.Children.Add(unit);retention.Children.Add(Row("Delete records older than",ageTools));var durationTools=new WrapPanel();durationTools.Children.Add(minimum);durationTools.Children.Add(SettingsVisual.Text("s",11,"#8994A6"));retention.Children.Add(Row("Minimum fight duration",durationTools));retention.Children.Add(Row("Maximum records",maximum));retention.Children.Add(SettingsVisual.Text("Records are saved after combat ends if the minimum duration is reached. At the storage limit, the oldest fight is removed. Optional age cleanup removes old fights. Deleting cannot be undone.",11,"#8994A6"));storage=new Expander{Header="History storage settings",Content=SettingsVisual.Card(retention,new Thickness(12)),Margin=new Thickness(0,0,0,12)};content.Children.Add(storage);
        count.Margin=new Thickness(0,0,0,8);content.Children.Add(count);content.Children.Add(Row("Filter by player",playerPicker));playerPicker.SelectionChanged+=delegate{if(loading)return;var item=playerPicker.SelectedItem as ComboBoxItem;playerFilter=item==null?null:item.Tag as string;Refresh(true);};var actions=new WrapPanel{Margin=new Thickness(0,0,0,10)};export=SettingsVisual.Button("Export TXT",Export);export.ToolTip="Exports the selected fight using the player filter.";clear=SettingsVisual.Button("Clear all history",delegate{owner.CombatHistory.Clear();Refresh(true);});foreach(var b in new[]{export,clear}){b.Margin=new Thickness(0,0,8,0);actions.Children.Add(b);}content.Children.Add(actions);
        encounters.Height=165;content.Children.Add(SettingsVisual.Card(encounters,new Thickness(6)));detail.Margin=new Thickness(0,12,0,8);content.Children.Add(detail);analysis=new DpsEncounterDetails(owner,null,delegate(uint actor){if(selected!=null){owner.CombatHistory.DeletePlayer(selected.Id,actor);Refresh(true);}});content.Children.Add(analysis);message.Margin=new Thickness(0,10,0,0);content.Children.Add(message);
        autoDelete.Click+=delegate{Changed();};age.Changed+=Changed;maximum.Changed+=Changed;minimum.Changed+=Changed;unit.SelectionChanged+=delegate{Changed();};encounters.SelectionChanged+=delegate{if(loading)return;var row=encounters.SelectedItem as DpsHistorySummary;selected=row==null?null:row.Record;ShowSelected();};Reload();
    }
    static Grid Row(string text,FrameworkElement control){var row=new Grid{MinHeight=45,Margin=new Thickness(0,4,0,4)};row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});row.Children.Add(SettingsVisual.Text(text,12));Grid.SetColumn(control,1);row.Children.Add(control);AutomationProperties.SetName(control,text);return row;}
    void Changed(){if(loading)return;var c=owner.Configuration;c.Dps.HistoryAutoDelete=autoDelete.IsChecked==true;c.Dps.HistoryAge=(int)age.Value;c.Dps.HistoryMaxRecords=(int)maximum.Value;c.Dps.HistoryMinimumSeconds=(int)minimum.Value;var item=unit.SelectedItem as ComboBoxItem;if(item!=null)c.Dps.HistoryAgeUnit=(string)item.Tag;owner.ApplyConfiguration(c);Reload();}
    internal void Reload(){loading=true;try{var o=owner.Configuration.Dps;autoDelete.IsChecked=o.HistoryAutoDelete;age.Value=o.HistoryAge;maximum.Value=o.HistoryMaxRecords;minimum.Value=o.HistoryMinimumSeconds;unit.SelectedIndex=o.HistoryAgeUnit=="hours"?0:1;age.IsEnabled=unit.IsEnabled=o.HistoryAutoDelete;if(language!=owner.Language){language=owner.Language;Columns();revision=-1;}UiLanguage.Apply(this,owner.Language);storage.Header=T("History storage settings");}finally{loading=false;}Refresh();}
    string T(string text){return UiLanguage.Text(text,owner.Language);}
    void Column(string label,string property,double weight,string format=null){var binding=new Binding(property){TargetNullValue="—"};if(format!=null)binding.StringFormat=format;encounters.Columns.Add(new DataGridTextColumn{Header=T(label),Binding=binding,Width=new DataGridLength(weight,DataGridLengthUnitType.Star),MinWidth=0});}
    void Columns(){encounters.Columns.Clear();var factory=new FrameworkElementFactory(typeof(Button));factory.SetValue(ContentControl.ContentProperty,T("Delete fight"));factory.SetValue(FrameworkElement.ToolTipProperty,T("Deletes the entire fight, including all its players."));factory.SetValue(Control.PaddingProperty,new Thickness(6,2,6,2));factory.AddHandler(Button.ClickEvent,new RoutedEventHandler(delegate(object sender,RoutedEventArgs e){var row=((Button)sender).DataContext as DpsHistorySummary;if(row!=null)DeleteFight(row);e.Handled=true;}));encounters.Columns.Add(new DataGridTemplateColumn{Header=T("Actions"),Width=105,CellTemplate=new DataTemplate{VisualTree=factory}});Column("Started","Started",2);Column("Duration","Duration",.8,"{0:0.0} s");Column("Players","Players",.6);Column("Damage","Damage",1,"{0:N0}");}
    internal void Refresh(bool force=false){if(!force&&!IsVisible)return;var o=owner.Configuration.Dps;string nextStyle=o.ShowSelfAsYou+o.DamageColor+o.HealerColor+o.TankColor+o.Color;long current=owner.CombatHistory.Revision;if(force||revision!=current||style!=nextStyle){style=nextStyle;revision=current;string id=selected==null?null:selected.Id;var records=owner.CombatHistory.Read();savedCount=records.Count;var names=new SortedSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var r in records)foreach(var p in r.Players)if(p.Name!=null)names.Add(p.Name);bool prior=loading;loading=true;try{playerPicker.Items.Clear();var all=new ComboBoxItem{Content=T("All players")};playerPicker.Items.Add(all);ComboBoxItem chosen=all;foreach(string name in names){var item=new ComboBoxItem{Content=name,Tag=name};playerPicker.Items.Add(item);if(name==playerFilter)chosen=item;}playerPicker.SelectedItem=chosen;playerFilter=chosen.Tag as string;var rows=new List<DpsHistorySummary>();foreach(var record in records){bool include=playerFilter==null;foreach(var p in record.Players)if(p.Name==playerFilter)include=true;if(include)rows.Add(new DpsHistorySummary{Record=record,PlayerFilter=playerFilter});}encounters.ItemsSource=rows;DpsHistorySummary match=null;foreach(var row in rows)if(row.Record.Id==id)match=row;encounters.SelectedItem=match??(rows.Count>0?rows[0]:null);selected=encounters.SelectedItem==null?null:((DpsHistorySummary)encounters.SelectedItem).Record;}finally{loading=prior;}clear.IsEnabled=records.Count>0;ShowSelected();}count.Text=T("Saved fights")+": "+savedCount+" / "+o.HistoryMaxRecords;string error=owner.CombatHistory.Error;message.Text=error==null?"":T("History storage error")+": "+error;}
    void ShowSelected(){export.IsEnabled=selected!=null;analysis.Set(selected,playerFilter);detail.Text=selected==null?T("No saved fights yet. Reach the minimum fight duration with the DPS meter enabled, then wait for its combat timeout."):T("Started")+": "+DpsHistory.LocalTime(selected.Started).ToString("yyyy-MM-dd HH:mm:ss")+" · "+T("End reason")+": "+T(selected.Reason);}
    void DeleteFight(DpsHistorySummary row){owner.CombatHistory.Delete(row.Record.Id);Refresh(true);}
    void Export(){if(selected==null)return;var dialog=new SaveFileDialog{Filter="Text file (*.txt)|*.txt",FileName="Aion2Helper-"+DpsHistory.LocalTime(selected.Started).ToString("yyyyMMdd-HHmmss")+".txt",Title=T("Export combat history")};if(dialog.ShowDialog(window)!=true)return;try{File.WriteAllText(dialog.FileName,DpsHistory.Text(selected,owner.Language,playerFilter),System.Text.Encoding.UTF8);message.Text=T("Export saved")+": "+dialog.FileName;}catch(Exception ex){message.Text=T("Export failed")+": "+ex.Message;}}
    internal void RenderDetails(string path){scroller.ScrollToVerticalOffset(220);SettingsVisual.RenderPreview(window,path);}
    internal void Verify(){Reload();if(age.IsEnabled!=owner.Configuration.Dps.HistoryAutoDelete||minimum.Value!=owner.Configuration.Dps.HistoryMinimumSeconds||maximum.Value!=owner.Configuration.Dps.HistoryMaxRecords)throw new Exception("History settings reload");if(encounters.Columns.Count!=5)throw new Exception("Compact encounter table");analysis.Verify();if(selected!=null){var summary=new DpsHistorySummary{Record=selected,PlayerFilter=selected.Players[0].Name};int before=selected.Players.Count;var held=selected;DeleteFight(summary);foreach(var r in owner.CombatHistory.Read())if(r.Id==held.Id)throw new Exception("Delete fight must remove the complete selected fight");if(held.Players.Count!=before)throw new Exception("Delete must not mutate held snapshots");}}
}
